/*
 * cdrom/cd-doom-load - Doom (USA)'s menu and level load, the drive's side of it, replayed (2026-11-15). GENERATED by
 * experiments/doomload/mkreplay.js from a Doom CD probe stream (0.rec, MiniLoops 4 to 6): do not edit the table
 * by hand. Needs Doom (USA) in the drive (lead-out 27:30; hwtests/cd-discid).
 *
 * WHY. Doom's E1M1 load is ~240M cycles; the consoles spread ~15M on it run to run and the emulator's engines differ by the
 * seeks alone (experiments/proposals/doom-level-load.md). The Doom CD probe times the game's own load on a console, one boot
 * a run and a RESET after it. This is the same conversation without the game: every command Doom's libcd writes from the
 * options menu's "Main Menu" to the level's first frame, at the game's own spacing - so a console repeats it, hands off, as
 * often as the spread needs, and the drive model is judged on the seeks a real game makes.
 *
 * WHAT IT DOES. Interrupts off, the CD's flags polled, Timer 2 at the system clock unwrapped in software (cd-game-steps'
 * clock and helpers). Init once, then REPS times the 72 steps below: each command is written DELAY cycles after the
 * interrupt the game wrote it after (its INT3; a Pause's or SeekP's INT2; a ReadN's last sector), and its interrupts are taken
 * as they come. The steps: Pause; six reads off PSXDOOM.WAD (00:34:08 and 00:50:13-33) each Setloc x2 / ReadN / n sectors /
 * Pause; Setmode 07h, Setloc 11:12:00, SeekP, Play (the menu's music, its reports acknowledged for as long as the menu stood);
 * Pause; Setmode 80h; the level's ten reads (06:31:71 ... 01:07:67 x289). No sector is read out of the buffer.
 *
 * READ IT LIKE THIS. A row per repeat and per part; every number is cycles. For a Pause or the SeekP: the command's write to
 * its INT2. For a ReadN: the write to the first INT1 (the seek, the settle, the wait for the sector), then the first INT1 to
 * the last. "total": the part's first write to its last interrupt. The first repeat starts from an Init, not from play.
 * A step that timed out or met an INT5 prints 0 and is counted at the end.
 *
 * ON THIS CORE: see GATES / STATUS when it is pinned (PREDICTED until a console has run it).
 * THE RULE: run it here first: `node hwtests/run.js cd-doom-load --disc=doom --ntsc --frames=42000 --quiet=6000 --settle=600`.
 */
#include <common.h>
#include <psxapi.h>
#include <io.h>

#define T2_COUNT 0x1F801120u
#define T2_MODE  0x1F801124u
#define MS(n) ((uint32_t)(n) * 33869u)
#define REPS 6
#define NSTEP 72
#define NMEAS 37

static volatile uint8_t *CD0 = (volatile uint8_t *)0x1F801800;
static volatile uint8_t *CD1 = (volatile uint8_t *)0x1F801801;
static volatile uint8_t *CD2 = (volatile uint8_t *)0x1F801802;
static volatile uint8_t *CD3 = (volatile uint8_t *)0x1F801803;
static void idx(uint8_t i) { *CD0 = i & 3; }
static uint8_t irqFlag() { idx(1); return *CD3 & 7; }
static void ackAll() { idx(1); *CD3 = 0x1F; }
static void param(uint8_t v) { idx(0); *CD2 = v; }
static void command(uint8_t c) { idx(0); *CD1 = c; }
static uint8_t resp() { idx(1); return *CD1; }
static bool hasResp() { return (*CD0 & 0x20) != 0; }
static void drain() { for (int n = 0; n < 32 && hasResp(); n++) resp(); }   /* rule 1: bounded (the FIFO holds 16) */

static uint32_t clk; static uint16_t lastT;
static uint32_t now() { const uint16_t t = read16(T2_COUNT); clk += (uint16_t)(t - lastT); lastT = t; return clk; }

/* The next interrupt: which and when; drained and acknowledged. A first read of 1 or 4 is read again (an old board's flag can
 * show 1 before 3, psx-spx "Unstable IRQ Flag polling"); every wait is bounded. */
struct Got { uint8_t flag; uint32_t t; };
static Got take(uint32_t limit) {
    Got g; g.flag = 0; g.t = 0;
    const uint32_t t0 = now();
    for (;;) {
        const uint32_t t = now();
        uint8_t f = irqFlag();
        if (f == 1 || f == 4) { const uint8_t f2 = irqFlag(); if (f2) f = f2; }
        if (f) { g.flag = f; g.t = t; break; }
        if (t - t0 > limit) { g.t = t; return g; }
    }
    drain(); ackAll();
    return g;
}
static Got takeKind(uint8_t k, uint32_t limit) {
    for (;;) { const Got g = take(limit); if (!g.flag || g.flag == k || g.flag == 5) return g; }
}
/* Wait until t, acknowledging what comes (the music's reports); how many came. */
static int strays;
static void idleUntil(uint32_t t) {
    while ((int32_t)(now() - t) < 0) { if (irqFlag()) { drain(); ackAll(); strays++; } }
}

struct Step { uint8_t cmd, np, p[3], kind; uint16_t n; uint32_t delay; };
/* kind 0: its INT3. 1: INT3, then INT2 (timed). 2: ReadN - INT3, then n INT1s (first and last timed). 3: Play - INT3; the next
 * step's delay counts from that INT3, the reports acknowledged meanwhile. */
static const Step STEP[NSTEP] = {
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,         0u },
    { 0x02, 3, { 0x00, 0x34, 0x08 }, 0,   0,   1126866u },
    { 0x02, 3, { 0x00, 0x34, 0x08 }, 0,   0,      4239u },
    { 0x06, 0, { 0x00, 0x00, 0x00 }, 2,   4,      2736u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,     19653u },
    { 0x02, 3, { 0x00, 0x50, 0x13 }, 0,   0,      5911u },
    { 0x02, 3, { 0x00, 0x50, 0x13 }, 0,   0,      4243u },
    { 0x06, 0, { 0x00, 0x00, 0x00 }, 2,  19,      2831u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,     21116u },
    { 0x02, 3, { 0x00, 0x34, 0x08 }, 0,   0,   1278779u },
    { 0x02, 3, { 0x00, 0x34, 0x08 }, 0,   0,     10852u },
    { 0x06, 0, { 0x00, 0x00, 0x00 }, 2,   3,      2886u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,     32259u },
    { 0x02, 3, { 0x00, 0x50, 0x31 }, 0,   0,      5895u },
    { 0x02, 3, { 0x00, 0x50, 0x31 }, 0,   0,      4203u },
    { 0x06, 0, { 0x00, 0x00, 0x00 }, 2,   3,      2759u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,     33559u },
    { 0x02, 3, { 0x00, 0x34, 0x08 }, 0,   0,      5734u },
    { 0x02, 3, { 0x00, 0x34, 0x08 }, 0,   0,      4124u },
    { 0x06, 0, { 0x00, 0x00, 0x00 }, 2,   2,      2799u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,     20923u },
    { 0x02, 3, { 0x00, 0x50, 0x33 }, 0,   0,      5450u },
    { 0x02, 3, { 0x00, 0x50, 0x33 }, 0,   0,      4269u },
    { 0x06, 0, { 0x00, 0x00, 0x00 }, 2,   2,      2732u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,     34906u },
    { 0x0e, 1, { 0x07, 0x00, 0x00 }, 0,   0,      2166u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,      3852u },
    { 0x02, 3, { 0x11, 0x12, 0x00 }, 0,   0,      4090u },
    { 0x16, 0, { 0x00, 0x00, 0x00 }, 1,   0,      2667u },
    { 0x03, 0, { 0x00, 0x00, 0x00 }, 3,   0,      3079u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0, 208630710u },
    { 0x0e, 1, { 0x80, 0x00, 0x00 }, 0,   0,  17731356u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,      3776u },
    { 0x02, 3, { 0x06, 0x31, 0x71 }, 0,   0,      4894u },
    { 0x02, 3, { 0x06, 0x31, 0x71 }, 0,   0,      4239u },
    { 0x06, 0, { 0x00, 0x00, 0x00 }, 2,   1,      2690u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,     19998u },
    { 0x02, 3, { 0x06, 0x31, 0x72 }, 0,   0,     48320u },
    { 0x06, 0, { 0x00, 0x00, 0x00 }, 2,   1,      2790u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,     25722u },
    { 0x02, 3, { 0x06, 0x32, 0x20 }, 0,   0,      4627u },
    { 0x02, 3, { 0x06, 0x32, 0x20 }, 0,   0,      3265u },
    { 0x06, 0, { 0x00, 0x00, 0x00 }, 2,  30,      2822u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,     22407u },
    { 0x02, 3, { 0x06, 0x45, 0x07 }, 0,   0,      5671u },
    { 0x02, 3, { 0x06, 0x45, 0x07 }, 0,   0,      3329u },
    { 0x06, 0, { 0x00, 0x00, 0x00 }, 2,  71,      2692u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,     41797u },
    { 0x02, 3, { 0x01, 0x05, 0x32 }, 0,   0,     73893u },
    { 0x02, 3, { 0x01, 0x05, 0x32 }, 0,   0,      4262u },
    { 0x06, 0, { 0x00, 0x00, 0x00 }, 2,   4,      2773u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,     19614u },
    { 0x02, 3, { 0x01, 0x05, 0x32 }, 0,   0,      5744u },
    { 0x02, 3, { 0x01, 0x05, 0x32 }, 0,   0,      4135u },
    { 0x06, 0, { 0x00, 0x00, 0x00 }, 2,  14,      2792u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,     43392u },
    { 0x02, 3, { 0x01, 0x37, 0x32 }, 0,   0,  10590950u },
    { 0x02, 3, { 0x01, 0x37, 0x32 }, 0,   0,      4181u },
    { 0x06, 0, { 0x00, 0x00, 0x00 }, 2,   4,      2702u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,     19646u },
    { 0x02, 3, { 0x01, 0x37, 0x32 }, 0,   0,      5500u },
    { 0x02, 3, { 0x01, 0x37, 0x32 }, 0,   0,      4168u },
    { 0x06, 0, { 0x00, 0x00, 0x00 }, 2,  45,      2680u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,     29153u },
    { 0x02, 3, { 0x01, 0x07, 0x67 }, 0,   0,   5303689u },
    { 0x02, 3, { 0x01, 0x07, 0x67 }, 0,   0,      4198u },
    { 0x06, 0, { 0x00, 0x00, 0x00 }, 2,   4,      2796u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,     19675u },
    { 0x02, 3, { 0x01, 0x07, 0x67 }, 0,   0,      5407u },
    { 0x02, 3, { 0x01, 0x07, 0x67 }, 0,   0,      4160u },
    { 0x06, 0, { 0x00, 0x00, 0x00 }, 2, 289,      2795u },
    { 0x09, 0, { 0x00, 0x00, 0x00 }, 1,   0,     27491u },
};
static uint32_t tA[REPS][NMEAS], tB[REPS][NMEAS], tPart[REPS][2];
static int bad;

int main() {
    printf("\ncdrom/cd-doom-load\n");
    printf("Doom (USA)'s menu and E1M1 load, its CD commands at the game's spacing, %d times. Needs Doom (USA) in the drive.\n", REPS);
    printf("About two minutes; nothing prints until the end.\n\n");
    EnterCriticalSection();
    const uint16_t m2 = read16(T2_MODE);
    write16(T2_MODE, 0);
    lastT = read16(T2_COUNT); clk = 0;
    idx(1); *CD2 = 0; ackAll(); drain();
    ackAll(); command(0x0A); take(MS(3000)); takeKind(2, MS(8000));       /* Init */
    ackAll(); param(0x80); command(0x0E); takeKind(3, MS(3000));
    { const uint32_t t = now() + MS(1000); idleUntil(t); }

    for (int rep = 0; rep < REPS && bad <= 8; rep++) {
        uint32_t anchor = now(), part0 = 0; int m = 0, part = 0;
        for (int s = 0; s < NSTEP && bad <= 8; s++) {   /* a drive that answers nothing ends the run in under two minutes */
            const Step &st = STEP[s];
            idleUntil(anchor + st.delay);
            ackAll();
            for (int k = 0; k < st.np; k++) param(st.p[k]);
            const uint32_t tw = now();
            command(st.cmd);
            if (s == 0 || (st.cmd == 0x09 && s > 0 && STEP[s - 1].kind == 3)) { if (s) { tPart[rep][0] = anchor - part0; part = 1; } part0 = tw; }
            Got g = takeKind(3, MS(3000));
            if (g.flag != 3) bad++;
            anchor = g.t;
            if (st.kind == 1) {
                g = takeKind(2, MS(10000));
                tA[rep][m] = g.flag == 2 ? g.t - tw : 0; tB[rep][m] = 0; m++;
                if (g.flag != 2) bad++;
                anchor = g.t;
            } else if (st.kind == 2) {
                g = takeKind(1, MS(10000));
                const uint32_t first = g.t; bool ok = g.flag == 1;
                for (int i = 1; ok && i < st.n; i++) { g = takeKind(1, MS(3000)); ok = g.flag == 1; }
                tA[rep][m] = ok ? first - tw : 0; tB[rep][m] = ok ? g.t - first : 0; m++;
                if (!ok) bad++;
                anchor = g.t;
            }
        }
        tPart[rep][part] = anchor - part0;
        ackAll(); command(0x09); takeKind(3, MS(3000)); takeKind(2, MS(5000));   /* (already paused: its INT2 comes at once) */
    }
    write16(T2_MODE, m2);
    ExitCriticalSection();

    printf("Per repeat, in the order written. P: a Pause's (or the SeekP's, marked S) write to its INT2. R lba xN: the ReadN's\n");
    printf("write to its first INT1, then first INT1 to last. Cycles.\n");
    for (int rep = 0; rep < REPS; rep++) {
        printf("repeat %d: menu total %9u, level total %9u\n", rep + 1, (unsigned)tPart[rep][0], (unsigned)tPart[rep][1]);
        int m = 0, loc = 0;
        for (int s = 0; s < NSTEP; s++) {
            const Step &st = STEP[s];
            if (st.cmd == 0x02) loc = ((st.p[0] >> 4) * 10 + (st.p[0] & 15)) * 4500 + ((st.p[1] >> 4) * 10 + (st.p[1] & 15)) * 75 + ((st.p[2] >> 4) * 10 + (st.p[2] & 15)) - 150;
            if (st.kind == 1) { printf("  %c %8u\n", st.cmd == 0x16 ? 'S' : 'P', (unsigned)tA[rep][m]); m++; }
            else if (st.kind == 2) { printf("  R %6d x%-3d %9u %9u\n", loc, st.n, (unsigned)tA[rep][m], (unsigned)tB[rep][m]); m++; }
        }
    }
    printf("steps that failed (a timeout or an INT5): %d; interrupts acknowledged between steps (the music's reports): %d\n", bad, strays);
    printf("\ncdrom/cd-doom-load: Done.\n");
    for (;;) VSync(0);
}
